class Solution {
    private long calc(long count, long val) {
        if (count == 0) return 0;
        if (val >= count) {
            return (2 * val - count + 1) * count / 2;
        }
        return val * (val + 1) / 2 + (count - val);
    }

    public int maxValue(int n, int index, int maxSum) {
        long low = 1, high = maxSum, ans = 1;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            long total = mid + calc(index, mid - 1) + calc(n - 1 - index, mid - 1);
            if (total <= maxSum) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return (int)ans;
    }
}

/**
 * @param {number} n
 * @param {number} index
 * @param {number} maxSum
 * @return {number}
 */
var maxValue = function(n, index, maxSum) {
    const calc = (count, val) => {
        if (count === 0) return 0n;
        const c = BigInt(count), v = BigInt(val);
        if (v >= c) {
            return (2n * v - c + 1n) * c / 2n;
        }
        return v * (v + 1n) / 2n + (c - v);
    };

    let low = 1n, high = BigInt(maxSum), ans = 1n;
    const targetSum = BigInt(maxSum);
    while (low <= high) {
        const mid = low + (high - low) / 2n;
        const total = mid + calc(index, mid - 1n) + calc(n - 1 - index, mid - 1n);
        if (total <= targetSum) {
            ans = mid;
            low = mid + 1n;
        } else {
            high = mid - 1n;
        }
    }
    return Number(ans);
};
